import json, sys

def truncate(s, n=400):
    s = s if isinstance(s, str) else json.dumps(s)
    return s if len(s) <= n else s[:n] + f"...[{len(s)}chars]"

for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    try:
        d = json.loads(line)
    except Exception:
        continue
    t = d.get("type")
    ts = d.get("timestamp", "")
    if t == "user":
        msg = d.get("message", {})
        content = msg.get("content")
        if isinstance(content, str):
            print(f"[{ts}] USER: {truncate(content)}")
        elif isinstance(content, list):
            for c in content:
                if c.get("type") == "text":
                    print(f"[{ts}] USER: {truncate(c.get('text',''))}")
                elif c.get("type") == "tool_result":
                    cont = c.get("content")
                    if isinstance(cont, list):
                        cont = " ".join(x.get("text","") for x in cont if isinstance(x, dict))
                    print(f"[{ts}] TOOL_RESULT: {truncate(cont, 200)}")
    elif t == "assistant":
        msg = d.get("message", {})
        content = msg.get("content", [])
        if isinstance(content, list):
            for c in content:
                if c.get("type") == "text":
                    print(f"[{ts}] ASSISTANT: {truncate(c.get('text',''))}")
                elif c.get("type") == "tool_use":
                    print(f"[{ts}] TOOL_USE: {c.get('name')} {truncate(c.get('input',{}), 150)}")

